{
    struct sctp_association *asoc;
    int ret = -EINVAL;

    asoc = sctp_id2assoc(sk, id);
    if (!asoc)
        return -EFAULT;

    if (asoc->ep->type != SOCK_STREAM)
        return -EOPNOTSUPP;

    if (asoc->ep->user_data) {
        ret = -EBUSY;
        goto out;
    }

    ret = sock_create_kern(&init_net, PF_INET, asoc->ep->type, IPPROTO_SCTP, sockp);
    if (ret < 0)
        goto out;

    sctp_copy_sock(*sockp, sk, asoc);
    sctp_assoc_migrate(asoc, *sockp);

