}

int sctp_peeloff(struct sock *sk, sctp_assoc_t id, struct socket **sockp) {
    struct sctp_association *asoc;
    int ret = -EINVAL;

    asoc = sctp_id2assoc(sk, id);
    if (!asoc)
        return -EFAULT;

    if (asoc->ep->type != SOCK_STREAM)
        return -EOPNOTSUPP;

    if (sk->sk_sleep && waitqueue_active(sk->sk_sleep))
        return -EBUSY;

    *sockp = sock_alloc();
    if (!*sockp)
        return -ENOMEM;

    sock_graft(sk, (*sockp));

    sctp_assoc_migrate(asoc, (*sockp)->sk);

    return 0;
}

int sctp_assoc_peeloff(struct sock *sk, sctp_assoc_t id, struct socket **sockp)
{
    int ret = -EINVAL;
    struct sctp_association *assoc = NULL;
    struct socket *new_sock = NULL;
    struct sock *new_sk = NULL;
    struct sctp_endpoint *ep = sctp_sk(sk)->ep;

    rcu_read_lock();
    assoc = sctp_id2assoc(ep, id);
    if (!assoc) {
        rcu_read_unlock();
        return -ENOENT;
    }

    if (!assoc->peer_supports_adaptation || !assoc->peer_supports_asconf) {
        rcu_read_unlock();
        return -EOPNOTSUPP;
    }

    rcu_read_unlock();

    ret = sock_create_kern(&init_net, sk->sk_family, sk->sk_type, sk->sk_protocol,
                           &new_sock);
    if (ret < 0)
        goto out;

    new_sk = new_sock->sk;
    sctp_sk(new_sk)->ep = ep;
    ep->base.sk = new_sk;

    if (sctp_assoc_copy(new_sk, sk, assoc) < 0)
        goto fail;

    sctp_assoc_migrate(assoc, new_sk);

    *sockp = new_sock;
    return 0;

fail:
    sock_release(new_sock);
out:
    return ret;
}

int sctp_peeloff(struct sock *sk, sctp_assoc_t id, struct socket **sockp)
{
    struct sctp_association *asoc;
    int ret = -EINVAL;

    asoc = sctp_id2assoc(sk, id);
    if (!asoc)
        return -EFAULT;

    if (sk->sk_sleep || !sockp)
        return -EINVAL;

    ret = sock_create(sk->sk_family, SOCK_STREAM, IPPROTO_SCTP, sockp);
    if (ret < 0)
        return ret;

    asoc->base.sk = (*sockp)->sk;

    return 0;
}

int sctp_peeloff(struct sock *sk, sctp_assoc_t id, struct socket **sockp)
{
    struct sctp_association *assoc;
    int ret = -EINVAL;

    assoc = sctp_id2assoc(sk, id);
    if (!assoc)
        return -ESOCKTNAM;

    if (sk->sk_sleep || !sockp)
        return -EBUSY;

    *sockp = sock_alloc();
    if (!*sockp)
        return -ENOMEM;

    sock_graft(sk, *sockp);

    /* Copy relevant properties from original socket to new one */
    (*sockp)->type = sk->sk_type;
    (*sockp)->ops = sk->sk_prot->sock_ops;

    sctp_association_migrate(assoc, *sockp);

    return 0;
}
